// ATF injects assertEqual, steps, outputs, stepResult and an enclosing try block - bare body.
function load(id) {
    var g = new GlideRecord('x_2298436_snackf_0_invoice');
    if (!g.get(id)) throw new Error('invoice not found: ' + id);
    return g;
}
function num(v) { return parseFloat(v) || 0; }

// steps(SYS_ID) is ATF's injected accessor for an earlier step's outputs. GEM {{ step[...] }}
// templates are NOT substituted in a script body, so the sys_id must be passed literally.
var aId = steps("1d78acfcbc8b412e89a22896c8bb1c7c").record_id;
var bId = steps("0a6d875ffb3d4902a32fab9d1f647c94").record_id;
if (!aId || ('' + aId).length !== 32) { throw new Error('unresolved step reference for aId: ' + aId); }
if (!bId || ('' + bId).length !== 32) { throw new Error('unresolved step reference for bId: ' + bId); }
var a = load(aId);
var b = load(bId);

// Derive the expected rate from the product master behind the order - never hardcoded.
function rateFor(invoiceGr) {
    var soId = invoiceGr.getValue('sales_order');
    var line = new GlideRecord('x_2298436_snackf_0_sales_order_detail');
    line.addQuery('sales_order', soId);
    line.query();
    if (!line.next()) throw new Error('no sales order line for ' + soId);
    var prod = new GlideRecord('x_2298436_snackf_0_product');
    if (!prod.get(line.getValue('product'))) throw new Error('product missing');
    return num(prod.getValue('gst_rate'));
}

var rateA = rateFor(a);
var taxableA = num(a.getValue('taxable_amount'));
var expectedGstA = Math.round(taxableA * rateA / 100 * 100) / 100;
var actualGstA = num(a.getValue('cgst_amount')) + num(a.getValue('sgst_amount')) + num(a.getValue('igst_amount'));
assertEqual({ name: 'intrastate GST total = taxable * product rate', shouldbe: expectedGstA, value: actualGstA });
assertEqual({
    name: 'intrastate invoice total = taxable + GST',
    shouldbe: Math.round((taxableA + expectedGstA) * 100) / 100,
    value: num(a.getValue('total_invoice_amount')),
});
assertEqual({ name: 'intrastate CGST equals SGST', shouldbe: num(a.getValue('cgst_amount')), value: num(a.getValue('sgst_amount')) });

var rateB = rateFor(b);
var taxableB = num(b.getValue('taxable_amount'));
var expectedGstB = Math.round(taxableB * rateB / 100 * 100) / 100;
var actualGstB = num(b.getValue('cgst_amount')) + num(b.getValue('sgst_amount')) + num(b.getValue('igst_amount'));
assertEqual({ name: 'interstate GST total = taxable * product rate', shouldbe: expectedGstB, value: actualGstB });
assertEqual({
    name: 'interstate invoice total = taxable + GST',
    shouldbe: Math.round((taxableB + expectedGstB) * 100) / 100,
    value: num(b.getValue('total_invoice_amount')),
});
assertEqual({ name: 'interstate GST carried wholly by IGST', shouldbe: expectedGstB, value: num(b.getValue('igst_amount')) });

// No GSTIN may be invented: both benchmark customers have a blank gstin, so the
// rule must leave invoice.customer_gstin blank rather than fabricating one.
assertEqual({ name: 'intrastate customer_gstin left blank', shouldbe: '', value: a.getValue('customer_gstin') || '' });
assertEqual({ name: 'interstate customer_gstin left blank', shouldbe: '', value: b.getValue('customer_gstin') || '' });

stepResult.setOutputMessage(
    'rate=' + rateA + '% | intrastate GST=' + actualGstA + ' total=' + a.getValue('total_invoice_amount') +
    ' | interstate IGST=' + b.getValue('igst_amount') + ' total=' + b.getValue('total_invoice_amount')
);
